    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // s
    I4 = R8;                                            // k
    DM(8, I7) = R12;                                    // out
    R0 = DM(1, I6);                                     // aux
    DM(9, I7) = R0;
    R0 = DM(2, I6);                                     // size
    DM(7, I7) = R0;
    R8 = DM(10, I4);
    R4 = DM(11, I4);
    F9 = RECIPS F8;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    DM(12, I4) = R9;
    R13 = DM(45, I1);                                   // rng = s->rng_
    R0 = DM(7, I7);
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _dpk_zd;
