_dpk_clr:
    DM(I3, M6) = R1;
_dpk_zd:
    I2 = I1;                                            // pt = the first particle
    R0 = 6;
    DM(10, I7) = R0;
_dpk_part:
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(8, I4);               // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
    R8 = FEXT R13 BY 0:16;                              // w & 0xFFFF
    R7 = R7 OR R6;                                      // itof_nonneg
    R8 = R8 OR R6;
    F7 = F7 - F6, R5 = DM(9, I4);
    F8 = F8 - F6;
    F7 = F7 * F5, R5 = DM(12, I4);                      // hi * 65536.0f
    F7 = F7 + F8, R6 = DM(10, I4);                      // + lo
    F8 = F7 * F5;                                       // / 4294967296.0f: q
    F4 = F6 * F8;
    F4 = F7 - F4;
    F4 = F4 * F5;
    F3 = F8 + F4;
    R9 = DM(0, I2);                                     // pre_gain = pt->pre_gain_
    R12 = DM(1, I2);                                    // g
    R11 = DM(2, I2);                                    // r
    R10 = DM(3, I2);                                    // h
    R15 = DM(4, I2);                                    // state_1
    R14 = DM(5, I2);                                    // state_2
    R0 = 1;
    DM(12, I7) = R0;                                    // can_randomize_frequency = 1
    R0 = DM(7, I4);
    R1 = 0;
    COMP(R0, R1);                                       // if (sync) u = density
    IF EQ JUMP _dpk_ns;
    R3 = DM(0, I4);
_dpk_ns:
    R0 = DM(8, I7);
    I0 = R0;
    R0 = DM(9, I7);
    I3 = R0;
    R0 = DM(7, I7);
    DM(11, I7) = R0;
    R1 = 0;
    COMP(R0, R1);
