_dpk_loop:
    R0 = 0;                                             // sample = 0.0f
    R1 = DM(0, I4);
    COMP(F3, F1);                                       // u <= density
    IF GT JUMP _dpk_imp;
    R2 = DM(1, I4);
    F0 = F3 * F2;                                       // sample = u * gain
    R1 = DM(12, I7);
    R2 = 0;
    COMP(R1, R2);
    IF EQ JUMP _dpk_imp;
    DM(13, I7) = R0;
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(8, I4);               // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
    R8 = FEXT R13 BY 0:16;                              // w & 0xFFFF
    R7 = R7 OR R6;                                      // itof_nonneg
    R8 = R8 OR R6;
    F7 = F7 - F6, R5 = DM(9, I4);
    F8 = F8 - F6;
    F7 = F7 * F5, R5 = DM(12, I4);                      // hi * 65536.0f
    F7 = F7 + F8, R6 = DM(10, I4);                      // + lo
    F8 = F7 * F5;                                       // / 4294967296.0f: q
    F4 = F6 * F8;
    F4 = F7 - F4;
    F4 = F4 * F5;
    F1 = F8 + F4;
    R2 = 0x40000000;
    F1 = F2 * F1;                                       // v = 2.0f * rng_float(&rng) - 1.0f
    R2 = 0x3F800000;
    F1 = F1 - F2;
    R2 = DM(3, I4);
    F1 = F2 * F1;                                       // SemitonesToRatio(spread * v)
    R2 = 0x43000000;
    F1 = F1 + F2;                                       // pitch = semitones + 128.0f
    R2 = TRUNC F1;                                      // pitch_integral
    R4 = 0x4B000000;
    R5 = R4 OR R2;
    F5 = F5 - F4;
    F1 = F1 - F5;                                       // pitch_fractional
    R2 = LSHIFT R2 BY 2;
    R4 = pl_lut_pitch_ratio_high.;
    .NOCOMPRESS;
    R2 = R2 + R4;
    .COMPRESS;
    I5 = R2;
    R4 = 0x43800000;
    F1 = F1 * F4;
    R5 = TRUNC F1;                                      // (int)(pitch_fractional * 256.0f)
    R5 = LSHIFT R5 BY 2;
    R2 = DM(I5, M5);                                    // lut_pitch_ratio_high[pitch_integral]
    R4 = pl_lut_pitch_ratio_low.;
    .NOCOMPRESS;
    R5 = R5 + R4;
    .COMPRESS;
    I5 = R5;
    R6 = DM(2, I4);
    R7 = 0x3E800000;
    R8 = DM(4, I4);
    R0 = 0x3F000000;
    R5 = DM(I5, M5);                                    // lut_pitch_ratio_low[..]
    F2 = F2 * F5;                                       // ratio
    F2 = F2 * F6;                                       // f = minf(ratio * f0, 0.25f)
    COMP(F2, F7);
    IF GE R2 = R7 OR R7;
    F1 = F8 * F2;                                       // q * f * sqrt_density
    R5 = DM(5, I4);
    F1 = F1 * F5;
    F4 = F0 * F1;                                       // pl_rsqrt: h = 0.5f * x
    R5 = 0;
    COMP(F1, F5);                                       // x > 0.0f
    IF GT JUMP _dpk_rs;
    R9 = 0;
    JUMP _dpk_rd;
_dpk_rs:
    R5 = -1;
    R1 = ASHIFT R1 BY R5;
    R5 = 0x5F3759DF;
    .NOCOMPRESS;
    R9 = R5 - R1;
    .COMPRESS;
    R0 = 0x3FC00000;
    F1 = F4 * F9;                                       // y = y * (1.5f - h * y * y)
    F1 = F1 * F9;
    F1 = F0 - F1;
    F9 = F9 * F1;
    F1 = F4 * F9;                                       // y = y * (1.5f - h * y * y)
    F1 = F1 * F9;
    F1 = F0 - F1;
    F9 = F9 * F1;
    F1 = F4 * F9;                                       // y = y * (1.5f - h * y * y)
    F1 = F1 * F9;
    F1 = F0 - F1;
    F9 = F9 * F1;
_dpk_rd:
    R0 = 0x3F000000;
    F9 = F0 * F9;                                       // pre_gain = 0.5f * ..
    R0 = 0x413957D7;
    F0 = F0 * F2;                                       // g = f * (M_PI_F + a * f * f)
    F0 = F0 * F2;
    R1 = 0x40490FDB;
    F0 = F1 + F0;
    F12 = F2 * F0;
    R11 = DM(6, I4);                                    // r = resonance_r
