    F5 = F10 - F5;
    F2 = F2 * F5;
    F5 = F0 * F2;
    F5 = F10 - F5;
    F2 = F2 * F5;
    F10 = F1 * F2;
    F5 = F0 * F10;
    F5 = F1 - F5;
    F5 = F5 * F2;
    F10 = F10 + F5;
