    F2 = F12 * F15;
    F1 = F1 - F2;
    F1 = F1 - F14;
    F1 = F1 * F10;
    F2 = F12 * F1;                                      // bp = g hp + s1
    F2 = F2 + F15;
    F15 = F12 * F1;                                     // s1 = g hp + bp
    F15 = F15 + F2;
    F0 = F12 * F2;                                      // lp = g bp + s2
    F0 = F0 + F14;
    F14 = F12 * F2;                                     // s2 = g bp + lp
    F14 = F14 + F0;
    R1 = DM(I0, M5);                                    // out[n] += bp
    F1 = F1 + F2;
    DM(I0, M6) = R1;
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(8, I4);               // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
