    L5 = DM(1, I7);
    L4 = DM(2, I7);
    L3 = DM(3, I7);
    L2 = DM(4, I7);
    L1 = DM(5, I7);
    L0 = DM(6, I7);
    M6 = DM(7, I7);
    I5 = DM(8, I7);
    I3 = DM(9, I7);
    I2 = DM(10, I7);
    I1 = DM(11, I7);
    I0 = DM(12, I7);
    I12 = DM(M7, I6);
