dust_tail_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = I3;
    DM(I7, M7) = R0;
    R0 = I5;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L3;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    R0 = L5;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L3 = 0;
    L4 = 0;
    L5 = 0;
    I7=MODIFY (I7,-16)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(0, I4);                                     // amount
    DM(7, I7) = R0;
    R0 = DM(1, I4);                                     // rt
    DM(8, I7) = R0;
    R0 = DM(1, I6);                                     // size
    DM(11, I7) = R0;
    R1 = DM(4142, I1);                                  // fresh_
    DM(12, I7) = R1;
    R1 = DM(41, I1);
    DM(13, I7) = R1;                                    // lp_decay_
    R1 = DM(42, I1);
    DM(14, I7) = R1;                                    // lfo_y1_
    R1 = DM(43, I1);
    DM(15, I7) = R1;                                    // lfo_y0_
    R15 = DM(44, I1);                                   // wp = write_ptr_
    R14 = I1;                                           // buffer_ (word 46)
    R1 = 184;
    .NOCOMPRESS;
    R14 = R14 + R1;
    .COMPRESS;
    R11 = 0x1FFF;                                       // DUST_MASK
    R10 = 0x8000;
    R9 = 0x4B000000;
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _dtk_end;
    R1 = DM(12, I7);
    R2 = 3412;
    COMP(R1, R2);                                       // every read past the C's cleared memory: the plain loop
    IF LT JUMP _dtc_loop;
_dtf_loop:
