    R1 = DM(39, I1);                                    // state_1_
    R2 = DM(40, I1);                                    // state_2_
    R3 = DM(37, I1);                                    // r_
    R4 = DM(36, I1);                                    // g_
    R5 = DM(38, I1);                                    // h_
    F6 = F3 * F1;                                       // hp = (x - r s1 - g s1 - s2) * h
    F6 = F0 - F6;
    F7 = F4 * F1;
    F6 = F6 - F7;
    F6 = F6 - F2;
    F6 = F6 * F5;
    F7 = F4 * F6;                                       // bp = g hp + s1
    F7 = F7 + F1;
    F1 = F4 * F6;                                       // s1 = g hp + bp
    F1 = F1 + F7;
    F0 = F4 * F7;                                       // lp = g bp + s2
    F0 = F0 + F2;
    F2 = F4 * F7;                                       // s2 = g bp + lp
    F2 = F2 + F0;
    DM(39, I1) = R1;
    DM(40, I1) = R2;
    DM(9, I7) = R0;                                     // in = out[n] (the low pass)
    R1 = 1;
    .NOCOMPRESS;
    R15 = R15 - R1;                                     // --wp
    .COMPRESS;
    R1 = 0;
    COMP(R15, R1);
    IF GE JUMP _dtf_w;
    R1 = 8192;
    .NOCOMPRESS;
    R15 = R15 + R1;
    .COMPRESS;
_dtf_w:
    R1 = 31;
    R1 = R15 AND R1;                                    // (wp & 31) == 0
    IF NE JUMP _dtf_l1;
    R1 = DM(15, I7);
    R2 = DM(14, I7);
    R3 = 0x3FFFFFF5;
    F3 = F3 * F1;                                       // y0 = 1.99999869f * y0 - y1
    F3 = F3 - F2;
    DM(15, I7) = R3;
    DM(14, I7) = R1;                                    // y1 = t
    JUMP _dtf_l2;
_dtf_l1:
    R1 = DM(14, I7);
_dtf_l2:
    R2 = 0x3F000000;
    F1 = F1 + F2;                                       // lfo = (t or y1) + 0.5f
    DM(10, I7) = R1;
    R12 = 0;                                            // prev = 0.0f
    R13 = DM(9, I7);                                    // acc = in
    R8 = 125;
    .NOCOMPRESS;
    R8 = R15 + R8;
    .COMPRESS;
    R0 = R8 AND R11;                                    // DUST_READ: i = ix & 8191
    R1 = -1;
    R2 = ASHIFT R0 BY R1;                               // i >> 1
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;
    .COMPRESS;
    I4 = R2;
    R1 = 1;
    R0 = R0 AND R1;                                     // i & 1
    R1 = 0x80000000;
    R2 = DM(I4, M5);                                    // w
    .NOCOMPRESS;
    R3 = R2 + R1;                                       // (r ^ 0x8000) of either half as (half + 0x8000) mod 2^16: no XOR in stock code
