    .NOCOMPRESS;
    R2 = R2 + R10;
    .COMPRESS;
    R3 = FEXT R3 BY 16:16;                              // (w >> 16) ^ 0x8000
    R2 = FEXT R2 BY 0:16;                               // (w & 0xFFFF) ^ 0x8000
    R1 = 0;
    COMP(R0, R1);
