    R2 = R2 OR R9;                                      // itof_nonneg
    F2 = F2 - F9;
    R1 = 0x47000000;
    F2 = F2 - F1;                                       // - 32768.0f
    R1 = 0x39800000;
    F4 = F2 * F1;                                       // * 0.000244140625f
