    R1 = 0x3F200000;
    F4 = F1 * F4;                                       // acc += r * scale
    F13 = F13 + F4;
    R8 = 0;
    .NOCOMPRESS;
    R8 = R15 + R8;
    .COMPRESS;
    R4 = 0x45800000;
    F4 = F13 * F4;                                      // DUST_WRITE: x = value * 4096.0f
    R5 = 0x46FFFE00;
    COMP(F4, F5);                                       // x > 32767.0f (a NaN too, as selcc compares): 32767
    IF GT R4 = R5 OR R5;
    R5 = 0xC7000000;
    COMP(F4, F5);                                       // x < -32768.0f: -32768
