    R5 = 0xFFFF;
    R4 = R4 AND R5;                                     // r = n & 0xFFFF
    R0 = R8 AND R11;                                    // i = ix & 8191
    R1 = -1;
    R2 = ASHIFT R0 BY R1;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;
    .COMPRESS;
    I4 = R2;
    R1 = 1;
    R0 = R0 AND R1;                                     // i & 1
    R6 = LSHIFT R4 BY 16;
    R7 = 0xFFFF0000;
    R2 = DM(I4, M5);                                    // w
    R3 = R2 AND R5;                                     // odd: (w & 0xFFFF) | (r << 16)
    R3 = R3 OR R6;
    R2 = R2 AND R7;                                     // even: (w & 0xFFFF0000) | r
    R2 = R2 OR R4;
    R1 = 0;
    COMP(R0, R1);
    IF NE R2 = R3 OR R3;
    DM(I4, M5) = R2;
    R1 = 0xBF200000;
